<?php
require __DIR__ . '/admin_common.php';
require __DIR__ . '/admin_layout.php';
admin_start('Archive', 'archive', $config);
$archivedList = array_values(array_filter($products, fn($product) => product_state($product) === 'archived'));
?>
<section class="panel"><div class="section-title"><div><div class="eyebrow">Permanent history</div><h2>Archive.</h2></div><p>Archived products remain available for order history, but they can never return to Live.</p></div><div style="display:grid;gap:7px;margin-bottom:25px;padding:16px 18px;border-left:3px solid var(--rose);background:#f8e9e5"><strong>Archive is permanent.</strong><span style="color:var(--muted);font-size:12px;line-height:1.6">Use Hidden when a product may return later. Use Archive only when you want to retire it permanently.</span></div><div class="product-list"><?php if (!$archivedList): ?><p style="color:var(--muted)">No products have been permanently archived.</p><?php endif; ?><?php foreach ($archivedList as $p): ?><div class="product-row"><?php if ($p['image_url']): ?><a href="<?=admin_h($p['image_url'])?>" target="_blank" rel="noreferrer" title="Open full-size image"><img class="thumb" src="<?=admin_h($p['image_url'])?>" alt="<?=admin_h($p['name'])?>"></a><?php else: ?><span class="thumb-placeholder">BL</span><?php endif; ?><div><h3><?=admin_h($p['name'])?></h3><p><strong style="color:var(--muted)">Archived permanently</strong> · <?=admin_h($p['archived_at'])?></p><div class="row-actions"><a href="/admin/products?view=archived&amp;edit=<?= (int) $p['id'] ?>">Edit record</a></div></div><div class="product-row-meta"><strong>₦<?=number_format($p['price_kobo'] / 100, 2)?></strong><span>History only</span></div></div><?php endforeach; ?></div></section>
